// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { HistoryIcon, Loader2Icon, SendIcon } from 'lucide-react'
import { Fragment } from 'react'

import { Chip, DemoStage, highlight, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, RESPONSE, TIMING } from './script'

const build: Build = ({ tl, q, qa, step, final, move, click, type, count, wait, cursorOut }) => {
  step(0)
  move('env', { at: 0.3 })
  click('env')
  tl.to(q('env'), { borderColor: 'rgba(34,211,238,0.7)', duration: 0.2 }, '<')
  move('url')
  click('url')
  type('url-text', '{{base}}/users/42', { speed: 0.045 })
  tl.fromTo(q('resolved'), { opacity: 0, y: -4 }, { opacity: 1, y: 0, duration: 0.3 })

  step(1, '+=0.5')
  move('send')
  click('send')
  tl.to(q('send-icon'), { opacity: 0, duration: 0.1 }, '<')
  tl.to(q('spinner'), { opacity: 1, rotate: 720, duration: 1.6, ease: 'none' }, '<')
  tl.to(q('resolved'), { opacity: 0, duration: 0.2 }, '<')
  tl.fromTo(
    qa('wf-bar'),
    { scaleX: 0 },
    { scaleX: 1, duration: 0.32, stagger: 0.3, ease: 'power2.out' },
    '<0.05',
  )
  tl.fromTo(qa('wf-row'), { opacity: 0.25 }, { opacity: 1, duration: 0.2, stagger: 0.3 }, '<')
  cursorOut('<0.6')

  step(2, '+=0.1')
  tl.to(q('spinner'), { opacity: 0, duration: 0.1 })
  tl.to(q('send-icon'), { opacity: 1, duration: 0.1 }, '<')
  tl.fromTo(
    q('status'),
    { scale: 0.4, opacity: 0 },
    { scale: 1, opacity: 1, duration: 0.5, ease: 'back.out(3)' },
    '<',
  )
  count('ms', 184, { at: '<', duration: 0.6 })
  count('kb', 1.2, { at: '<', duration: 0.6, decimals: 1, suffix: ' KB' })
  tl.set(q('response'), { opacity: 1 }, '<')
  tl.fromTo(
    qa('res-line'),
    { opacity: 0, x: 10 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.09 },
    '<0.1',
  )
  tl.fromTo(q('history'), { opacity: 0, x: 30 }, { opacity: 1, x: 0, duration: 0.5 }, '<0.3')

  step(3, '+=0.6')
  move('diff')
  click('diff')
  tl.to(
    q('diff'),
    { backgroundColor: 'rgba(34,211,238,0.18)', color: '#f4f4f6', duration: 0.2 },
    '<',
  )
  tl.fromTo(
    q('diff-old'),
    { opacity: 0, height: 0 },
    { opacity: 1, height: 18, duration: 0.4, ease: 'power3.out' },
    '<0.1',
  )
  tl.to(qa('res-line')[3], { backgroundColor: 'rgba(52,211,153,0.16)', duration: 0.3 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.8)
  tl.to([q('response'), q('history'), q('status')], { opacity: 0, duration: 0.4 })
}

export default function Demo() {
  return (
    <DemoStage
      label="Request Builder sending a GET request with an environment variable, showing timing, the response and a diff"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome aside={<Chip d="env">● staging</Chip>}>
        <div className="flex h-full flex-col gap-2.5">
          <div className="relative flex items-center gap-2">
            <span className="rounded-md bg-emerald/15 px-2 py-1.5 font-mono text-[10.5px] font-semibold text-emerald">
              GET
            </span>
            <span
              data-d="url"
              className="flex h-8 flex-1 items-center rounded-lg border border-line bg-canvas/80 px-2.5 font-mono text-[11px]"
            >
              <span data-d="url-text" className="demo-caret text-ink-soft" />
            </span>
            <span
              data-d="send"
              className="relative flex h-8 items-center gap-1.5 rounded-lg bg-[var(--accent)] px-3 text-[11px] font-medium text-canvas"
            >
              <SendIcon data-d="send-icon" className="size-3.5" />
              <Loader2Icon data-d="spinner" className="absolute left-3 size-3.5 opacity-0" />
              Send
            </span>
            <span
              data-d="resolved"
              className="absolute left-12 top-full mt-1 rounded bg-elevated px-2 py-0.5 font-mono text-[9.5px] text-cyan opacity-0 shadow"
            >
              base → https://staging.api.dev
            </span>
          </div>
          <div className="flex gap-3 border-b border-line pb-1.5 text-[10.5px] text-muted">
            <span className="text-ink">Params</span>
            <span>Headers 3</span>
            <span>Body</span>
            <span>Scripts</span>
            <span data-d="diff" className="ml-auto rounded px-1.5 text-[var(--accent)]">
              Diff
            </span>
          </div>
          <div className="grid min-h-0 flex-1 grid-cols-[130px_1fr] gap-3">
            <div className="space-y-1.5">
              {TIMING.map((phase) => (
                <div key={phase.label} data-d="wf-row" className="opacity-25">
                  <span className="text-[9px] text-muted">{phase.label}</span>
                  <span className="relative mt-0.5 block h-1.5 rounded-full bg-white/[0.06]">
                    <span
                      data-d="wf-bar"
                      className="absolute inset-y-0 origin-left scale-x-0 rounded-full bg-[var(--accent)]"
                      style={{ left: `${phase.start}%`, width: `${phase.width}%` }}
                    />
                  </span>
                </div>
              ))}
              <div
                data-d="history"
                className="mt-2 flex items-center gap-1.5 rounded-lg border border-line bg-canvas/60 px-2 py-1.5 text-[9.5px] text-ink-soft opacity-0"
              >
                <HistoryIcon className="size-3 text-muted" /> GET /users/42
              </div>
            </div>
            <div className="min-w-0">
              <div className="mb-1.5 flex items-center gap-2 text-[10px]">
                <span
                  data-d="status"
                  className="rounded bg-emerald/15 px-1.5 py-0.5 font-mono font-semibold text-emerald opacity-0"
                >
                  200 OK
                </span>
                <span className="font-mono text-muted">
                  <span data-d="ms">0</span> ms
                </span>
                <span data-d="kb" className="font-mono text-muted">
                  0 KB
                </span>
              </div>
              <div
                data-d="response"
                className="rounded-xl border border-line bg-canvas/80 p-3 font-mono text-[11.5px] leading-[1.65] opacity-0"
              >
                {RESPONSE.split('\n').map((line, index) => (
                  <Fragment key={index}>
                    {index === 3 ? (
                      <div
                        data-d="diff-old"
                        className="-mx-1.5 h-0 overflow-hidden whitespace-pre rounded bg-rose/15 px-1.5 leading-[18px] text-rose opacity-0"
                      >
                        {'  "plan": "free",'}
                      </div>
                    ) : null}
                    <div data-d="res-line" className="-mx-1.5 whitespace-pre rounded px-1.5">
                      {highlight(line)}
                    </div>
                  </Fragment>
                ))}
              </div>
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
